sp_widget.client_script:
api.controller = function($window, $element, $timeout) {

    var c = this;

    /* Existing Explore navigation */
    c.goToExplore = function() {

		$window.location.replace(
			'/campusmatch?id=campusmatch_explore'
		);

	};


    /* ================================
       MOBILE HERO BACKGROUND FIX
       ================================ */

    function forceHeroBackground() {

        // Only for mobile / Now Mobile sized screens
        if (!$window.matchMedia('(max-width: 768px)').matches) {
            return;
        }

        var hero = $element[0].querySelector('.cm-home-hero');

        if (!hero) {
            return;
        }

        hero.style.setProperty(
            'background-image',
            'url("https://res.cloudinary.com/dn9sdbv1o/image/upload/v1789811391/Mobile_View_BG_hin003.png")',
            'important'
        );

        hero.style.setProperty(
            'background-size',
            'cover',
            'important'
        );

        hero.style.setProperty(
            'background-position',
            'center center',
            'important'
        );

        hero.style.setProperty(
            'background-repeat',
            'no-repeat',
            'important'
        );
    }


    /*
     * MAB/WebView can repaint after the widget initially loads.
     * Apply again after rendering settles.
     */
    $timeout(forceHeroBackground, 0);
    $timeout(forceHeroBackground, 250);
    $timeout(forceHeroBackground, 750);
    $timeout(forceHeroBackground, 1500);

};

sp_widget.css:
/* =========================================================
   CAMPUSMATCH HOME HERO
========================================================= */

.cm-home-hero {

  position: relative;

  width: 100vw;
  max-width: 100vw;

  margin-left: calc(50% - 50vw);
  margin-right: calc(50% - 50vw);

  min-height: calc(100vh - 86px);
  min-height: calc(100svh - 86px);

  overflow: hidden;

  box-sizing: border-box;

  background-image:
    url("https://res.cloudinary.com/dn9sdbv1o/image/upload/v1789450440/Landing_Page_f0v0sk.png");

  background-size: cover;

  background-position: center;

  background-repeat: no-repeat;

  font-family:
    "DM Sans",
    "Segoe UI",
    sans-serif;
}


/* =========================================================
   PREVENT HORIZONTAL SCROLL
========================================================= */

html,
body {

  margin: 0;

  overflow-x: hidden;
}


/* =========================================================
   HERO BOX SIZING
========================================================= */

.cm-home-hero,
.cm-home-hero *,
.cm-home-hero *::before,
.cm-home-hero *::after {

  box-sizing: border-box;
}


/* =========================================================
   VERY LIGHT READABILITY LAYER
========================================================= */

.cm-hero-overlay {

  position: absolute;

  inset: 0;

  pointer-events: none;

  background:
    linear-gradient(
      90deg,
      rgba(255,255,255,0.26) 0%,
      rgba(255,255,255,0.10) 40%,
      rgba(255,255,255,0) 68%
    );
}


/* =========================================================
   CONTAINER
========================================================= */

.cm-hero-container {

  position: relative;

  z-index: 2;

  width: 100%;

  max-width: 1280px;

  min-height: calc(100vh - 86px);
  min-height: calc(100svh - 86px);

  margin: 0 auto;

  padding:
    66px
    40px
    55px;

  display: flex;

  align-items: center;

  box-sizing: border-box;
}


/* =========================================================
   CONTENT
========================================================= */

.cm-hero-content {

  width: 100%;

  max-width: 650px;
}


/* =========================================================
   EYEBROW
========================================================= */

.cm-eyebrow {

  width: fit-content;

  display: inline-flex;

  align-items: center;

  gap: 9px;

  margin-bottom: 28px;

  padding:
    10px
    20px;

  border-radius: 999px;

  background:
    rgba(237, 245, 233, 0.94);

  color: #104E45;

  font-weight: 700;

  font-size: 16px;

  box-shadow:
    0 8px 24px rgba(16, 78, 69, 0.06);
}


.cm-star {

  color: #104E45;

  font-size: 18px;
}


/* =========================================================
   TITLE
========================================================= */

.cm-hero-title {

  margin:
    0
    0
    28px;

  font-family:
    "Plus Jakarta Sans",
    "Segoe UI",
    sans-serif;

  font-size:
    clamp(
      50px,
      5.2vw,
      76px
    );

  line-height: 1.02;

  letter-spacing: -2.8px;

  font-weight: 700;

  color: #064B40;
}


.cm-hero-title span {

  color: #149A72;
}


/* =========================================================
   DESCRIPTION
========================================================= */

.cm-hero-description {

  max-width: 540px;

  color: #315E70;

  font-size: 20px;

  line-height: 1.55;

  font-weight: 400;
}


/* =========================================================
   ACTIONS
========================================================= */

.cm-hero-actions {

  width: 100%;

  max-width: 450px;

  display: flex;

  flex-direction: column;

  gap: 12px;

  margin-bottom: 10px;
}


.cm-btn {

  min-height: 64px;

  width: 80%;

  padding:
    16px
    26px;

  display: flex;

  align-items: center;

  gap: 10px;

  border-radius: 999px;

  font-size: 18px;

  font-weight: 700;

  text-decoration: none !important;

  transition:
    transform .2s ease,
    box-shadow .2s ease,
    background .2s ease;
}


.cm-btn svg {

  width: 25px;

  height: 25px;

  flex-shrink: 0;
}


.cm-btn .cm-arrow {

  margin-left: auto;

  font-size: 27px;

  font-weight: 400;
}


/* =========================================================
   PRIMARY BUTTON
========================================================= */

.cm-btn-primary {

  color: #FFFFFF !important;

  background:
    linear-gradient(
      90deg,
      #0E5A4D,
      #147B64
    );

  box-shadow:
    0 12px 28px rgba(16, 78, 69, 0.18);
}


.cm-btn-primary:hover {

  color: #FFFFFF !important;

  transform: translateY(-2px);

  box-shadow:
    0 16px 34px rgba(16, 78, 69, 0.24);
}


/* =========================================================
   SECONDARY BUTTON
========================================================= */

.cm-btn-secondary {

  color: #064B40 !important;

  background:
    rgba(255,255,255,0.94);

  border:
    1.5px solid
    rgba(21, 86, 75, 0.22);

  box-shadow:
    0 8px 22px rgba(16, 78, 69, 0.07);
}


.cm-btn-secondary:hover {

  color: #064B40 !important;

  transform: translateY(-2px);

  border-color: #249D78;

  box-shadow:
    0 13px 28px rgba(16, 78, 69, 0.12);
}


/* =========================================================
   EXPLORE LINK
========================================================= */

.cm-explore-link {

  display: inline-flex;

  align-items: center;

  gap: 8px;

  color: #08785F !important;

  font-size: 18px;

  font-weight: 700;

  text-decoration: none !important;
}


.cm-explore-link span {

  font-size: 28px;

  transition:
    transform .2s ease;
}


.cm-explore-link:hover {

  color: #075F4D !important;

  text-decoration: none !important;
}


.cm-explore-link:hover span {

  transform: translateX(5px);
}


/* =========================================================
   SCROLL HINT
========================================================= */

.cm-scroll-hint {

  position: absolute;

  z-index: 3;

  bottom: 24px;

  left: 50%;

  transform: translateX(-50%);

  display: none;

  flex-direction: column;

  align-items: center;

  gap: 5px;

  color: #315E70;

  font-size: 13px;

  font-weight: 600;
}


.cm-scroll-circle {

  width: 42px;

  height: 42px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 50%;

  background:
    rgba(255,255,255,.92);

  border:
    1px solid
    rgba(210,222,216,.8);

  color: #104E45;

  font-size: 22px;

  box-shadow:
    0 5px 18px rgba(16,78,69,.08);
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 1000px) {

  .cm-home-hero {

    background-image:
      url("https://res.cloudinary.com/dn9sdbv1o/image/upload/v1790231093/Tablet_BG_owoo9q.jpg");

    background-size: cover;

    background-position: center;

    background-repeat: no-repeat;
  }


  .cm-hero-container {

    padding:
      50px
      28px
      46px;
  }


  .cm-hero-content {

    max-width: 590px;
  }


  .cm-hero-title {

    font-size: 46px;

    line-height: 1.03;

    letter-spacing: -2.2px;

    margin-bottom: 23px;
  }


  .cm-hero-description {

    max-width: 500px;

    font-size: 15px;

    line-height: 1.5;

    margin-bottom: 20px;
  }


  .cm-hero-actions {

    max-width: 420px;

    gap: 10px;

    margin-bottom: 12px;
  }


  .cm-btn {

    width: 80%;

    min-height: 56px;

    padding:
      12px
      20px;

    font-size: 16px;

    gap: 9px;
  }


  .cm-btn svg {

    width: 21px;

    height: 21px;
  }


  .cm-btn .cm-arrow {

    font-size: 23px;
  }


  .cm-explore-link {

    color: #08785F !important;

    font-size: 17px;

    font-weight: 700;

    gap: 6px;
  }


  .cm-explore-link .cm-explore-arrow {

    color: #08785F !important;
  }

}


/* =========================================================
   MOBILE APP VIEW
========================================================= */

@media (max-width: 768px) {

  .cm-home-hero {

    min-height:
      calc(100svh - 76px);

    background-image:
      url("https://res.cloudinary.com/dn9sdbv1o/image/upload/v1789811391/Mobile_View_BG_hin003.png");

    background-position:
      center bottom;

    background-size:
      cover;

    background-repeat:
      no-repeat;
  }


  .cm-hero-overlay {

    background:
      linear-gradient(
        180deg,
        rgba(255,255,255,.02) 0%,
        rgba(255,255,255,.08) 42%,
        rgba(255,255,255,.02) 100%
      );
  }


  .cm-hero-container {

    min-height:
      calc(100svh - 76px);

    padding:
      50px
      28px
      115px;

    align-items:
      flex-start;
  }


  .cm-hero-content {

    max-width: 100%;
  }


  .cm-eyebrow {

    margin-bottom: 28px;

    padding:
      9px
      17px;

    font-size: 14px;
  }


  .cm-hero-title {

    max-width: 620px;

    margin-bottom: 26px;

    font-size:
      clamp(
        42px,
        10vw,
        58px
      );

    letter-spacing: -2px;
  }


  .cm-hero-description {

    max-width: 520px;

    font-size: 17px;

    line-height: 1.55;

    margin-bottom: 30px;
  }


  .cm-hero-actions {

    max-width: 430px;

    margin-top: 0;

    gap: 8px;
  }

}


/* =========================================================
   PHONE
========================================================= */

@media (max-width: 560px) {

  .cm-home-hero {

    background-image:
      url("https://res.cloudinary.com/dn9sdbv1o/image/upload/v1789811391/Mobile_View_BG_hin003.png");

    min-height:
      calc(100svh - 72px);

    background-size:
      cover;

    background-position:
      center bottom;

    background-repeat:
      no-repeat;
  }


  .cm-hero-container {

    min-height:
      calc(100svh - 72px);

    padding:
      42px
      22px
      125px;
  }


  .cm-eyebrow {

    font-size: 13px;

    gap: 7px;

    padding:
      8px
      14px;

    margin-bottom: 24px;
  }


  .cm-hero-title {

    font-size: 36px;

    line-height: 1.04;

    letter-spacing: -1.7px;

    margin-bottom: 20px;
  }


  .cm-hero-description {

    margin-bottom: 14px;

    max-width: 92%;

    font-size: 16px;

    line-height: 1.55;
  }


  .cm-btn {

    min-height: 41px;

    padding:
      10px
      20px;

    font-size: 16px;
  }


  .cm-btn svg {

    width: 16px;

    height: 16px;
  }


  .cm-explore-link {

    font-size: 16px;

    color: #08785F !important;

    font-weight: 700;
  }


  .cm-explore-link .cm-explore-arrow {

    color: #08785F !important;
  }

}


/* =========================================================
   VERY SMALL PHONE
========================================================= */

@media (max-width: 390px) {

  .cm-hero-container {

    padding-left: 18px;

    padding-right: 18px;
  }


  .cm-hero-title {

    font-size: 28px;
  }


  .cm-hero-description {

    font-size: 12px;
  }


  .cm-explore-link {

    font-size: 14px;

    color: #08785F !important;

    font-weight: 700;

    display: inline-flex;

    align-items: center;

    gap: 4px;
  }


  .cm-explore-arrow {

    transform: translateY(-2px);
  }


  .cm-btn {

    padding:
      0
      14px;

    font-size: 12px;
  }


  .cm-btn svg {

    width: 14px;

    height: 14px;
  }

}


/* =========================================================
   LAPTOP / DESKTOP ONLY
   MOVE FULL HERO CONTENT TO LEFT
========================================================= */

@media (min-width: 1001px) {

  .cm-hero-container {

    max-width: none;

    margin-left: 0;
    margin-right: 0;

    padding-left: 4%;
    padding-right: 40px;
  }


  .cm-hero-content {

    margin-left: 0;

    margin-right: auto;
  }

}


/* =========================================================
   DESKTOP FINAL VIEWPORT FIT
   HEADER = 64PX
   HERO = REMAINING SCREEN
========================================================= */

@media (min-width: 1001px) {

  .cm-home-hero {

    min-height:
      calc(100vh - 64px);

    min-height:
      calc(100svh - 64px);

    background-position:
      center bottom;
  }


  .cm-hero-container {

    min-height:
      calc(100vh - 64px);

    min-height:
      calc(100svh - 64px);

    padding-top: 38px;

    padding-bottom: 28px;
  }


  .cm-hero-content {

    max-width: 540px;
  }


  .cm-eyebrow {

    margin-bottom: 20px;

    padding:
      8px
      16px;

    gap: 7px;

    font-size: 13px;
  }


  .cm-star {

    font-size: 15px;
  }


  .cm-hero-title {

    margin-bottom: 20px;

    font-size:
      clamp(
        40px,
        3.9vw,
        57px
      );

    line-height: 1.03;

    letter-spacing: -2px;
  }


  .cm-hero-description {

    max-width: 470px;

    margin-bottom: 18px;

    font-size: 15px;

    line-height: 1.5;
  }


  .cm-hero-actions {

    max-width: 390px;

    gap: 9px;

    margin-bottom: 8px;
  }


  .cm-btn {

    width: 80%;

    min-height: 49px;

    padding:
      11px
      20px;

    font-size: 14px;

    gap: 8px;
  }


  .cm-btn svg {

    width: 19px;

    height: 19px;
  }


  .cm-btn .cm-arrow {

    font-size: 22px;
  }


  .cm-explore-link {

    gap: 6px;

    font-size: 14px;
  }


  .cm-explore-link span {

    font-size: 22px;
  }

}


/* =========================================================
   LARGE DESKTOP
========================================================= */

@media (min-width: 1450px) {

  .cm-hero-content {

    max-width: 560px;
  }


  .cm-hero-title {

    font-size: 58px;
  }

}
